annual['Return'] = (annual['Last_Close'] / annual['First_Close'] - 1) * 100
annual_returns = annual[annual['Year'] <= 2025]

best_years = annual_returns.nlargest(5, 'Return')[['Year', 'Return']].values.tolist()
worst_years = annual_returns.nsmallest(5, 'Return')[['Year', 'Return']].values.tolist()

# Decades
